function pongShot(angle, velocity, targetAngle, height, mouse, keys) {
  if (mouse && keys[" "]) return {kind:"smash",spin:0};
  if (mouse && (keys.z || keys.x)) return {kind:"spin",spin:keys.z?-1:1};
  if (!mouse && height >= .23 && Math.abs(velocity) >= 2.7 && Math.abs(angle) < targetAngle*.82) {
    return {kind:"smash",spin:0};
  }
  if (!mouse && Math.abs(angle) >= Math.max(7,targetAngle*.66) && Math.abs(velocity) >= .85) {
    return {kind:"spin",spin:Math.sign(angle)};
  }
  return {kind:"normal",spin:0};
}
function pongFlight(shot, speed, height, startZ, targetZ, gravity, netHeight, ballRadius) {
  if (shot !== "smash") return (shot === "spin" ? .91 : .80) / speed;
  const fraction = startZ / (startZ - targetZ);
  const gravityArc = .5 * -gravity * fraction * (1-fraction);
  const clearance = netHeight + ballRadius + .025 - height * (1-fraction) - ballRadius * fraction;
  const netTime = Math.sqrt(Math.max(0,clearance)/gravityArc);
  return Math.max(.53/speed,netTime);
}
